    'name_too_long' => ('That name is too long.', 'नाम बहुत लंबा है।'),
    'invalid_price' => ('Enter the price in whole rupees.', 'कीमत पूरे रुपयों में डालें।'),
    'invalid_stockQty' || 'invalid_lowStockAt' => ('Enter stock as a whole number (0 or more).', 'स्टॉक पूरी संख्या में डालें (0 या ज़्यादा)।'),
