    'too_many_variants' => ('At most 20 sizes per item.', 'एक आइटम में ज़्यादा से ज़्यादा 20 साइज़।'),
    'too_many_groups' => ('At most 10 add-on groups per item.', 'एक आइटम में ज़्यादा से ज़्यादा 10 ऐड-ऑन ग्रुप।'),
    'invalid_image' => ('That photo couldn\'t be used. Try another.', 'यह फ़ोटो इस्तेमाल नहीं हो सकी। दूसरी चुनें।'),
    'invalid_hours' => ('Set both opening and closing time (they can\'t be the same).', 'खुलने और बंद होने का समय दोनों डालें (दोनों एक जैसे नहीं हो सकते)।'),
