    'no_fulfilment' => ('Keep delivery or self-pickup on.', 'डिलीवरी या सेल्फ़-पिकअप में से एक चालू रखें।'),
    'invalid_pincode' => ('Enter a 6-digit pincode.', '6 अंकों का पिनकोड डालें।'),
    'invalid_address' || 'invalid_location' => ('Set the shop address and map location.', 'दुकान का पता और नक्शे पर जगह डालें।'),
    'invalid_dates' => ('Check the dates: the end can\'t be before the start.', 'तारीखें जाँचें: खत्म होने की तारीख शुरू से पहले नहीं हो सकती।'),
    'in_the_past' => ('That date has already passed.', 'यह तारीख निकल चुकी है।'),
    'too_many_holidays' => ('You already have 30 upcoming holidays.', 'आपकी पहले से 30 आने वाली छुट्टियाँ हैं।'),
    'invalid_close_for' => ('Choose how long to close for.', 'कितनी देर बंद रखना है, चुनें।'),
    'nothing_to_change' => ('Nothing has changed.', 'कुछ नहीं बदला।'),
    'not_found' => ('We couldn\'t find that.', 'यह नहीं मिला।'),
    'not_configured' || 'backend_not_configured' => ('The server isn\'t set up yet.', 'सर्वर अभी तैयार नहीं है।'),
